-- BAD_AI_READY Part 2: reviewed and executable AI Ready remediation SQL.
--
-- This file is based on the remediation categories generated by the Skill report.
-- The generic draft comments have been replaced with demo-specific business meaning,
-- and the PK/FK/freshness/source candidates have been finalized for this dataset.
--
-- Run as BAD_AI_READY after 02_load_csv.sql.
-- The packaged CSV data is already unique and referentially consistent, so every
-- ENABLE VALIDATE primary-key and foreign-key statement below can be applied directly.

set define off
set verify off
set feedback on
set serveroutput on
set timing on
set pagesize 200
set linesize 240

whenever sqlerror exit sql.sqlcode rollback

begin
  if user <> 'BAD_AI_READY' then
    raise_application_error(-20001, 'Connect as BAD_AI_READY before running this script.');
  end if;
end;
/

prompt ============================================================================
prompt 1. Add freshness and source metadata columns
prompt ============================================================================

declare
  procedure add_column_if_missing(
    p_table_name  in varchar2,
    p_column_name in varchar2,
    p_definition  in varchar2
  ) is
    l_count pls_integer;
  begin
    select count(*)
      into l_count
      from user_tab_columns
     where table_name = upper(p_table_name)
       and column_name = upper(p_column_name);

    if l_count = 0 then
      execute immediate 'alter table "' || upper(p_table_name) || '" add ("' ||
                        upper(p_column_name) || '" ' || p_definition || ')';
      dbms_output.put_line('Added ' || upper(p_table_name) || '.' || upper(p_column_name));
    else
      dbms_output.put_line('Already exists: ' || upper(p_table_name) || '.' || upper(p_column_name));
    end if;
  end;
begin
  add_column_if_missing('AI_DOCUMENTS', 'UPDATED_AT', 'TIMESTAMP(6)');
  add_column_if_missing('AI_DOCUMENTS', 'SOURCE_SYSTEM', 'VARCHAR2(30)');
  add_column_if_missing('CUSTOMER_FEATURES', 'UPDATED_AT', 'TIMESTAMP(6)');
  add_column_if_missing('CUSTOMER_FEATURES', 'SOURCE_SYSTEM', 'VARCHAR2(30)');
  add_column_if_missing('EMPTY_EXPORT', 'UPDATED_AT', 'TIMESTAMP(6)');
  add_column_if_missing('EMPTY_EXPORT', 'SOURCE_SYSTEM', 'VARCHAR2(30)');
  add_column_if_missing('ORPHAN_REGIONS', 'UPDATED_AT', 'TIMESTAMP(6)');
  add_column_if_missing('ORPHAN_REGIONS', 'SOURCE_SYSTEM', 'VARCHAR2(30)');
  add_column_if_missing('RAW_CUSTOMERS', 'UPDATED_AT', 'TIMESTAMP(6)');
  add_column_if_missing('RAW_CUSTOMERS', 'SOURCE_SYSTEM', 'VARCHAR2(30)');
  add_column_if_missing('RAW_ORDERS', 'UPDATED_AT', 'TIMESTAMP(6)');
  add_column_if_missing('RAW_ORDERS', 'SOURCE_SYSTEM', 'VARCHAR2(30)');
  add_column_if_missing('RAW_ORDER_LINES', 'UPDATED_AT', 'TIMESTAMP(6)');
  add_column_if_missing('RAW_ORDER_LINES', 'SOURCE_SYSTEM', 'VARCHAR2(30)');
  add_column_if_missing('SUPPORT_TICKETS', 'UPDATED_AT', 'TIMESTAMP(6)');
  add_column_if_missing('SUPPORT_TICKETS', 'SOURCE_SYSTEM', 'VARCHAR2(30)');
end;
/

declare
  l_sql varchar2(4000);
begin
  update "AI_DOCUMENTS" set "UPDATED_AT" = coalesce("UPDATED_AT", systimestamp), "SOURCE_SYSTEM" = coalesce("SOURCE_SYSTEM", 'PART2_CSV');
  execute immediate 'alter table "AI_DOCUMENTS" modify ("UPDATED_AT" default systimestamp not null, "SOURCE_SYSTEM" default ''PART2_CSV'' not null)';
  update "CUSTOMER_FEATURES" set "UPDATED_AT" = coalesce("UPDATED_AT", systimestamp), "SOURCE_SYSTEM" = coalesce("SOURCE_SYSTEM", 'PART2_CSV');
  execute immediate 'alter table "CUSTOMER_FEATURES" modify ("UPDATED_AT" default systimestamp not null, "SOURCE_SYSTEM" default ''PART2_CSV'' not null)';
  update "EMPTY_EXPORT" set "UPDATED_AT" = coalesce("UPDATED_AT", systimestamp), "SOURCE_SYSTEM" = coalesce("SOURCE_SYSTEM", 'PART2_CSV');
  execute immediate 'alter table "EMPTY_EXPORT" modify ("UPDATED_AT" default systimestamp not null, "SOURCE_SYSTEM" default ''PART2_CSV'' not null)';
  update "ORPHAN_REGIONS" set "UPDATED_AT" = coalesce("UPDATED_AT", systimestamp), "SOURCE_SYSTEM" = coalesce("SOURCE_SYSTEM", 'PART2_CSV');
  execute immediate 'alter table "ORPHAN_REGIONS" modify ("UPDATED_AT" default systimestamp not null, "SOURCE_SYSTEM" default ''PART2_CSV'' not null)';
  update "RAW_CUSTOMERS" set "UPDATED_AT" = coalesce("UPDATED_AT", systimestamp), "SOURCE_SYSTEM" = coalesce("SOURCE_SYSTEM", 'PART2_CSV');
  execute immediate 'alter table "RAW_CUSTOMERS" modify ("UPDATED_AT" default systimestamp not null, "SOURCE_SYSTEM" default ''PART2_CSV'' not null)';
  update "RAW_ORDERS" set "UPDATED_AT" = coalesce("UPDATED_AT", systimestamp), "SOURCE_SYSTEM" = coalesce("SOURCE_SYSTEM", 'PART2_CSV');
  execute immediate 'alter table "RAW_ORDERS" modify ("UPDATED_AT" default systimestamp not null, "SOURCE_SYSTEM" default ''PART2_CSV'' not null)';
  update "RAW_ORDER_LINES" set "UPDATED_AT" = coalesce("UPDATED_AT", systimestamp), "SOURCE_SYSTEM" = coalesce("SOURCE_SYSTEM", 'PART2_CSV');
  execute immediate 'alter table "RAW_ORDER_LINES" modify ("UPDATED_AT" default systimestamp not null, "SOURCE_SYSTEM" default ''PART2_CSV'' not null)';
  update "SUPPORT_TICKETS" set "UPDATED_AT" = coalesce("UPDATED_AT", systimestamp), "SOURCE_SYSTEM" = coalesce("SOURCE_SYSTEM", 'PART2_CSV');
  execute immediate 'alter table "SUPPORT_TICKETS" modify ("UPDATED_AT" default systimestamp not null, "SOURCE_SYSTEM" default ''PART2_CSV'' not null)';
end;
/

prompt ============================================================================
prompt 2. Add reviewed primary keys and foreign keys with validation
prompt ============================================================================

declare
  procedure add_constraint_if_missing(
    p_constraint_name in varchar2,
    p_ddl             in varchar2
  ) is
    l_count pls_integer;
  begin
    select count(*)
      into l_count
      from user_constraints
     where constraint_name = upper(p_constraint_name);

    if l_count = 0 then
      execute immediate p_ddl;
      dbms_output.put_line('Added constraint ' || upper(p_constraint_name));
    else
      dbms_output.put_line('Already exists: ' || upper(p_constraint_name));
    end if;
  end;
begin
  add_constraint_if_missing('PK_ORPHAN_REGIONS',
    'alter table "ORPHAN_REGIONS" add constraint "PK_ORPHAN_REGIONS" primary key ("COUNTRY_CODE") enable validate');
  add_constraint_if_missing('PK_RAW_CUSTOMERS',
    'alter table "RAW_CUSTOMERS" add constraint "PK_RAW_CUSTOMERS" primary key ("CUSTOMER_ID") enable validate');
  add_constraint_if_missing('PK_RAW_ORDERS',
    'alter table "RAW_ORDERS" add constraint "PK_RAW_ORDERS" primary key ("ORDER_ID") enable validate');
  add_constraint_if_missing('PK_RAW_ORDER_LINES',
    'alter table "RAW_ORDER_LINES" add constraint "PK_RAW_ORDER_LINES" primary key ("ORDER_ID", "LINE_NO") enable validate');
  add_constraint_if_missing('PK_AI_DOCUMENTS',
    'alter table "AI_DOCUMENTS" add constraint "PK_AI_DOCUMENTS" primary key ("DOC_ID", "CHUNK_NUMBER") enable validate');
  add_constraint_if_missing('PK_CUSTOMER_FEATURES',
    'alter table "CUSTOMER_FEATURES" add constraint "PK_CUSTOMER_FEATURES" primary key ("CUSTOMER_ID") enable validate');
  add_constraint_if_missing('PK_SUPPORT_TICKETS',
    'alter table "SUPPORT_TICKETS" add constraint "PK_SUPPORT_TICKETS" primary key ("TICKET_ID") enable validate');
  add_constraint_if_missing('PK_EMPTY_EXPORT',
    'alter table "EMPTY_EXPORT" add constraint "PK_EMPTY_EXPORT" primary key ("EXPORT_ID") enable validate');

  add_constraint_if_missing('FK_CUSTOMERS_REGION',
    'alter table "RAW_CUSTOMERS" add constraint "FK_CUSTOMERS_REGION" foreign key ("COUNTRY_CODE") references "ORPHAN_REGIONS" ("COUNTRY_CODE") enable validate');
  add_constraint_if_missing('FK_ORDERS_CUSTOMER',
    'alter table "RAW_ORDERS" add constraint "FK_ORDERS_CUSTOMER" foreign key ("CUSTOMER_ID") references "RAW_CUSTOMERS" ("CUSTOMER_ID") enable validate');
  add_constraint_if_missing('FK_LINES_ORDER',
    'alter table "RAW_ORDER_LINES" add constraint "FK_LINES_ORDER" foreign key ("ORDER_ID") references "RAW_ORDERS" ("ORDER_ID") enable validate');
  add_constraint_if_missing('FK_FEATURES_CUSTOMER',
    'alter table "CUSTOMER_FEATURES" add constraint "FK_FEATURES_CUSTOMER" foreign key ("CUSTOMER_ID") references "RAW_CUSTOMERS" ("CUSTOMER_ID") enable validate');
  add_constraint_if_missing('FK_TICKETS_CUSTOMER',
    'alter table "SUPPORT_TICKETS" add constraint "FK_TICKETS_CUSTOMER" foreign key ("CUSTOMER_ID") references "RAW_CUSTOMERS" ("CUSTOMER_ID") enable validate');
end;
/

prompt ============================================================================
prompt 3. Apply reviewed table comments
prompt ============================================================================
COMMENT ON TABLE "BAD_AI_READY"."AI_DOCUMENTS" IS '社内FAQや運用手順などの検索対象文書を1チャンク1行で保持する。粒度は文書チャンク、更新はデモCSV取込単位。AIはBODY_TEXTを検索対象とし、ORIGIN_URIを回答根拠の参照先として使用する。';
COMMENT ON TABLE "BAD_AI_READY"."CUSTOMER_FEATURES" IS '顧客分析用の特徴量を1顧客1行で保持する。粒度は顧客、更新はデモCSV取込単位。AIはセグメント説明や離反傾向の集計に使用し、個人を断定する用途には使用しない。';
COMMENT ON TABLE "BAD_AI_READY"."EMPTY_EXPORT" IS '外部出力ジョブの定義または結果を保持する予約表。粒度は1出力。デモでは空表であり、AIはデータが存在しないことを前提に扱う。';
COMMENT ON TABLE "BAD_AI_READY"."ORPHAN_REGIONS" IS '国コードと地域名、業務上のリスク区分を保持する参照マスタ。粒度は1国コード、更新はデモCSV取込単位。RAW_CUSTOMERSの国コード解釈に使用する。';
COMMENT ON TABLE "BAD_AI_READY"."RAW_CUSTOMERS" IS '顧客マスタのデモ取込データを1顧客1行で保持する。粒度は顧客、更新はデモCSV取込単位。連絡先や識別情報を含むため、AI回答では必要最小限の項目だけを使用する。';
COMMENT ON TABLE "BAD_AI_READY"."RAW_ORDERS" IS '注文ヘッダーを1注文1行で保持する。粒度は注文、更新はデモCSV取込単位。金額集計ではAMOUNT_TXTを数値へ変換し、通貨はCURRENCY_CODEと組み合わせて解釈する。';
COMMENT ON TABLE "BAD_AI_READY"."RAW_ORDER_LINES" IS '注文明細を1注文内の1明細1行で保持する。粒度は注文IDと明細番号の組合せ。数量、単価、割引率は文字列数値として保持するため、AI集計時は数値変換する。';
COMMENT ON TABLE "BAD_AI_READY"."SUPPORT_TICKETS" IS '顧客サポート問い合わせを1チケット1行で保持する。粒度はチケット、更新はデモCSV取込単位。本文に連絡先が含まれる可能性があるため、AI要約では個人情報を出力しない。';

