COMMENT ON COLUMN "BAD_AI_READY"."SUPPORT_TICKETS"."SEVERITY_TXT" IS '問い合わせ重大度を1から5の整数文字列で保持する。5が最も重大。';
COMMENT ON COLUMN "BAD_AI_READY"."SUPPORT_TICKETS"."AGENT_EMAIL" IS '担当エージェントの社内メールアドレス。合成データ。個人情報候補として扱う。';
COMMENT ON COLUMN "BAD_AI_READY"."SUPPORT_TICKETS"."REQUESTER_PHONE" IS '問い合わせ元の電話番号。合成データ。個人情報候補であり、AI回答には表示しない。';
COMMENT ON COLUMN "BAD_AI_READY"."SUPPORT_TICKETS"."TICKET_STATUS" IS '問い合わせ状態。許容値はOPEN、IN_PROGRESS、RESOLVED、CLOSED。';
COMMENT ON COLUMN "BAD_AI_READY"."SUPPORT_TICKETS"."PROBLEM_DESCRIPTION" IS '問い合わせ内容の本文。連絡先などを含む可能性があるため、AI要約では個人情報を除外する。';
COMMENT ON COLUMN "BAD_AI_READY"."SUPPORT_TICKETS"."RESOLUTION_TEXT" IS '解決内容。未解決の場合はNULL。解決済み問い合わせではナレッジ候補として利用できる。';
COMMENT ON COLUMN "BAD_AI_READY"."SUPPORT_TICKETS"."UPDATED_AT" IS 'この行が最後に更新されたデータベース日時。AI回答でデータ鮮度を説明するために使用する。';
COMMENT ON COLUMN "BAD_AI_READY"."SUPPORT_TICKETS"."SOURCE_SYSTEM" IS 'この行を提供した元システム識別子。本デモではPART2_CSVを設定する。';

prompt ============================================================================
prompt 5. Remove intentionally broad PUBLIC data grants when present
prompt ============================================================================

declare
begin
  for r in (
    select table_name, privilege
      from user_tab_privs_made
     where grantee = 'PUBLIC'
       and table_name in (
         'AI_DOCUMENTS','CUSTOMER_FEATURES','EMPTY_EXPORT','ORPHAN_REGIONS',
         'RAW_CUSTOMERS','RAW_ORDERS','RAW_ORDER_LINES','SUPPORT_TICKETS'
       )
       and privilege in ('SELECT', 'READ')
  ) loop
    execute immediate 'revoke ' || r.privilege || ' on "' || r.table_name || '" from PUBLIC';
    dbms_output.put_line('Revoked ' || r.privilege || ' on ' || r.table_name || ' from PUBLIC');
  end loop;
end;
/

prompt ============================================================================
prompt 6. Gather optimizer statistics after structural changes
prompt ============================================================================

begin
  for r in (
    select table_name
      from user_tables
     where table_name in (
       'AI_DOCUMENTS','CUSTOMER_FEATURES','EMPTY_EXPORT','ORPHAN_REGIONS',
       'RAW_CUSTOMERS','RAW_ORDERS','RAW_ORDER_LINES','SUPPORT_TICKETS'
     )
     order by table_name
  ) loop
    dbms_stats.gather_table_stats(
      ownname          => user,
      tabname          => r.table_name,
      estimate_percent => dbms_stats.auto_sample_size,
      cascade          => true,
      method_opt       => 'FOR ALL COLUMNS SIZE AUTO',
      no_invalidate    => false
    );
    dbms_output.put_line('Gathered statistics for ' || r.table_name);
  end loop;
end;
/

prompt ============================================================================
prompt 7. Compact post-remediation summary
prompt ============================================================================

column metric format a44
column value format 999999

select 'Target tables' metric, count(*) value
  from user_tables
 where table_name in ('AI_DOCUMENTS','CUSTOMER_FEATURES','EMPTY_EXPORT','ORPHAN_REGIONS','RAW_CUSTOMERS','RAW_ORDERS','RAW_ORDER_LINES','SUPPORT_TICKETS')
union all
select 'Table comments', count(*)
  from user_tab_comments
 where table_type = 'TABLE'
   and table_name in ('AI_DOCUMENTS','CUSTOMER_FEATURES','EMPTY_EXPORT','ORPHAN_REGIONS','RAW_CUSTOMERS','RAW_ORDERS','RAW_ORDER_LINES','SUPPORT_TICKETS')
   and comments is not null
union all
select 'Commented columns', count(*)
  from user_col_comments
 where table_name in ('AI_DOCUMENTS','CUSTOMER_FEATURES','EMPTY_EXPORT','ORPHAN_REGIONS','RAW_CUSTOMERS','RAW_ORDERS','RAW_ORDER_LINES','SUPPORT_TICKETS')
   and comments is not null
union all
select 'Primary keys', count(*)
  from user_constraints
 where table_name in ('AI_DOCUMENTS','CUSTOMER_FEATURES','EMPTY_EXPORT','ORPHAN_REGIONS','RAW_CUSTOMERS','RAW_ORDERS','RAW_ORDER_LINES','SUPPORT_TICKETS')
   and constraint_type = 'P'
union all
select 'Foreign keys', count(*)
  from user_constraints
 where table_name in ('AI_DOCUMENTS','CUSTOMER_FEATURES','EMPTY_EXPORT','ORPHAN_REGIONS','RAW_CUSTOMERS','RAW_ORDERS','RAW_ORDER_LINES','SUPPORT_TICKETS')
   and constraint_type = 'R'
union all
select 'Tables with UPDATED_AT', count(distinct table_name)
  from user_tab_columns
 where table_name in ('AI_DOCUMENTS','CUSTOMER_FEATURES','EMPTY_EXPORT','ORPHAN_REGIONS','RAW_CUSTOMERS','RAW_ORDERS','RAW_ORDER_LINES','SUPPORT_TICKETS')
   and column_name = 'UPDATED_AT'
union all
select 'Tables with SOURCE_SYSTEM', count(distinct table_name)
  from user_tab_columns
 where table_name in ('AI_DOCUMENTS','CUSTOMER_FEATURES','EMPTY_EXPORT','ORPHAN_REGIONS','RAW_CUSTOMERS','RAW_ORDERS','RAW_ORDER_LINES','SUPPORT_TICKETS')
   and column_name = 'SOURCE_SYSTEM'
union all
select 'Tables with optimizer statistics', count(*)
  from user_tables
 where table_name in ('AI_DOCUMENTS','CUSTOMER_FEATURES','EMPTY_EXPORT','ORPHAN_REGIONS','RAW_CUSTOMERS','RAW_ORDERS','RAW_ORDER_LINES','SUPPORT_TICKETS')
   and last_analyzed is not null
union all
select 'Broad PUBLIC SELECT or READ grants', count(*)
  from user_tab_privs_made
 where grantee = 'PUBLIC'
   and table_name in ('AI_DOCUMENTS','CUSTOMER_FEATURES','EMPTY_EXPORT','ORPHAN_REGIONS','RAW_CUSTOMERS','RAW_ORDERS','RAW_ORDER_LINES','SUPPORT_TICKETS')
   and privilege in ('SELECT','READ');

